    data=[
    ('01','startup-financing-problem-fit','互联网投融资笔记：融资要解决哪一个经营问题','business17','融资不是产品成立的证据。先说明资金要把哪个已验证环节扩展到什么阶段，才有讨论基础。',
     '需求是否存在、交付是否成立和规模是否可扩展，是不同的不确定性。资金可以延长验证时间，却不能自动提高产品价值。融资计划应对应可观察的阶段目标，而不是只用招聘人数和办公室规模表达进展。',
     '用一份虚构项目计划列出当前证据、未验证假设、资金用途和验收条件。每项支出都关联一个能改变下一步决策的问题。','text','current_evidence -> unresolved_assumption\nfunding_use -> experiment_or_capacity\nmilestone -> observable_customer_or_delivery_result',
     [('只有注册量没有关键行为','不能直接证明商业模式成立','用户任务完成与重复使用'),('资金用途只有扩大团队','需要进一步说明能力缺口','新增岗位与交付目标的关系'),('已有稳定履约但容量不足','可以测算扩大容量的条件','单位贡献与可复制的流程')],
     '融资可能带来治理和退出约束，不能只比较账面金额。这里是经营分析框架，不推荐任何具体融资产品或交易。','经营问题|先判断当前主要约束>现有证据|区分已验证与待验证>资金用途|关联具体能力和实验>阶段目标|按可观察结果决定继续'),
    ('01','startup-pre-post-money-dilution','互联网投融资笔记：投前、投后与稀释的简单演算','business17','说出让百分之二十股权时，需要先明确分母是投前还是投后，以及是否包含其他安排。',
     '在没有其他调整的简单模型里，投后估值等于投前估值加新增投资，新增投资比例由投资额除以投后估值计算。期权池、可转换工具和优先权会改变实际经济结果，不能把简化比例视为完整交易。',
     '用投前八百与新增二百的同单位假设演算，再比较下一轮增发对旧股东比例的影响。所有数字都是教学参数。','text','pre_money = 800\ninvestment = 200\npost_money = 1000\nnew_investor_ratio = 200 / 1000 = 20%\nold_holder_new_ratio = old_ratio * 80%',
     [('把投资额除以投前估值','会得到不同且不对应该模型的比例','分子分母的实际含义'),('下一轮再次新增股权','旧股东比例会继续稀释','每轮投后总股本'),('另设期权池或特殊权利','简单比例不足以解释最终权益','完整条款与股权表口径')],
     '股权比例不是现金收益，也不代表控制权。实际协议需要专业审查，本文只解释明确假设下的算术关系。','投前基础|明确已有股权与估值口径>新增资金|限定简单增发模型>投后分母|统一计算新增比例>后续稀释|逐轮更新完整股权表'),
    ('01','startup-data-room-evidence','互联网投融资笔记：资料包应让数字能追溯','business17','同一个收入数字在汇报、合同表和银行流水中口径不同，会使经营判断失去基础。',
     '资料包应区分合同额、确认收入、开票与回款，分别标注期间和来源。业务预测与已实现数据不能混排。技术资产也需要区分自研、开源依赖和第三方授权，不能把能运行的演示一概称为自有知识产权。',
     '先建立索引页，只向需要的角色开放必要资料。公开交流使用匿名汇总，原合同和个人信息保留在受控位置。','text','metric -> definition -> period -> source\nforecast -> assumptions -> sensitivity\nsoftware -> ownership -> dependency -> license\naccess -> reviewer_role -> permitted_scope',
     [('合同额高而回款很少','需要单独解释收款和履约条件','合同与现金各自来源'),('预测混入已实现数据','应拆开标示不同确定性','事实截止点和预测假设'),('演示含第三方组件','要核对授权而非声称全部自研','组件来源与使用许可')],
     '资料完整不保证融资成功，但能提高讨论可核对性。披露范围要与交易阶段匹配，不能为追求完整随意公开敏感材料。','指标定义|统一业务与财务口径>来源索引|数字能回到可核对依据>权限范围|按审阅角色限制资料>讨论结论|事实预测与判断分别表达'),
    ('02','company-cash-runway-scenarios','公司经营笔记：现金还能支撑多久要按情景计算','business17','把现金余额除以本月支出，得到的月份数可能忽略回款延迟和一次性付款。',
     '可用现金要扣除已受限制或必须预留的部分，未来流入按实际收款条件估算。固定支出、项目支出与资本性采购有不同节奏。简单 runway（现金支撑期）只适合稳定假设，项目型公司更需要按月列收付款。',
     '建立基准、回款延后和新增支出三种情景，观察最低现金点。不要把尚未签约的机会全部计作确定流入。','text','closing_cash[t] = opening_cash[t] + receipts[t] - payments[t]\nscenario A: expected collection\nscenario B: collection delayed\nscenario C: delayed collection + committed purchase',
     [('回款比预计晚一个月','现金低点可能早于账面盈利期','付款日期与实际回款条件'),('存在已承诺的大额采购','不能只按平均月支出估算','合同付款节点'),('商机尚未签约','应作为情景而非确定现金','证据等级与转化假设')],
     '模型需要随实际收付款更新。现金预测不能替代正式财务报表，也不应把不确定回款写成无条件保证。','可用现金|扣除限制与必要预留>收付款表|按真实节点展开时间>情景变化|改变回款和支出假设>最低余额|关注资金缺口出现时点'),
    ('02','company-project-contribution-cost','公司经营笔记：项目毛利里哪些成本容易漏掉','business17','项目报价看起来有利润，交付后却不赚钱，可能是实施、差旅、返工和售后没有进入估算。',
     '报价拆成角色任务和可交付物，再估算投入。直接采购、外协、现场与研发人天分别计入，公共费用的分摊口径需要保持一致。收入、成本确认和现金支付也不是同一天发生。',
     '用虚构项目列任务、负责人角色、工作量、费率与假设。实际执行后回填投入，比较偏差来自估算、范围变化还是返工。','text','task_cost = person_days * internal_daily_cost\nproject_direct_cost = labor + purchase + subcontract + site_cost\ncontribution = comparable_revenue - defined_direct_cost',
     [('漏掉现场调试人天','名义毛利可能被高估','任务范围与实际投入'),('需求增加但价格不变','应识别范围变化对成本的影响','变更记录与新增工作'),('只看到账现金减采购','无法完整解释项目收益','人工与未付成本口径')],
     '成本模型的关键是口径透明，并非制造精确到个位的假象。未知条件应保留区间和预备量，再随证据缩小。','交付范围|按任务和成果拆解>投入估算|人天采购现场分别计算>执行回填|记录真实资源与变更>偏差复盘|区分估算范围与返工原因'),
    ('02','company-scope-change-control','公司经营笔记：需求变更要连到工期和验收','business17','客户说“顺手加一个小功能”，实际可能改变接口、数据结构和验收路径。小改动需要先看影响。',
     '变更描述应包括触发场景、目标行为、范围外内容和依赖。评估不仅是编码时间，还包括设计、联调、历史数据兼容和复验。已确认基线提供比较对象，避免每次讨论都重定义原需求。',
     '用一张变更单连接原需求、变化内容、工作量和验收条件。未经确认的建议保留为待评估，不自动进入承诺交付。','text','baseline -> requested_delta\nimpact -> roles, dependencies, schedule, cost\nacceptance -> concrete inputs and expected behavior\ndecision -> confirmed scope and version',
     [('只改变字段显示名称','影响可能主要在展示与文档','接口及历史数据是否也受影响'),('新增跨系统写入','需要重新评估权限和失败恢复','外部依赖与事务边界'),('口头讨论尚未确认','不能当成已承诺范围','最终决策与版本依据')],
     '流程应与变更规模匹配，不能让简单修正陷入冗长审批。但影响外部承诺和核心数据时，确认依据必须清楚。','已确认基线|保留原需求和验收口径>变更请求|描述具体场景与差异>影响评估|联动工期成本和依赖>确认版本|执行依据能回溯到决策'),
    ('03','postgres96-connection-schema','深入 PostgreSQL：先确认连到哪台库和哪个 schema','pg17','表明明存在却提示找不到，或查到另一组数据，先别急着重建表。连接目标与搜索路径需要核对。',
     '服务器、数据库、用户和 schema 都参与对象定位。search_path 决定未限定名称按什么顺序解析，同名表可能存在于不同模式。连接池配置与手工终端不一致时，两边看到的对象自然不同。',
     '从实际出错连接执行只读身份查询，再用模式限定表名。避免只在另一终端连接里证明数据库正常。','sql','SELECT version(), current_database(), current_user;\nSHOW search_path;\nSELECT current_schema();\nSELECT count(*) FROM demo.orders;',
     [('两个模式都有 orders','未限定名称可能定位不同对象','search_path 与实际表模式'),('手工连接正常而应用失败','比较应用真实连接参数','数据库用户和目标实例'),('角色没有模式使用权限','表存在也可能无法访问','schema 与表的权限分别检查')],
     '搜索路径还会影响安全边界。应用账号只应拥有所需模式和对象权限，不要通过提升为超级用户掩盖配置问题。','连接身份|主机数据库用户分别确认>搜索路径|解析未限定对象名称>模式对象|使用明确 schema 核对表>权限范围|按最小需要授予访问'),
    ('03','postgres96-encoding-timezone','深入 PostgreSQL：编码、时区与时间字段语义','pg17','同一时刻在两台机器显示不同，可能是时区呈现差异；乱码则需要沿字符编码链路分析。',
     'timestamptz 表达绝对时刻并按会话时区展示，timestamp without time zone 不携带相同的时区语义。字符集编码和时区是两套配置。把本地墙上时间当绝对时刻保存，会让跨时区与夏令时处理复杂。',
     '查询服务器与客户端编码、会话时区，再切换演示会话时区读取同一时刻。业务日期字段与事件时刻分别设计。','sql','SHOW server_encoding;\nSHOW client_encoding;\nSHOW TimeZone;\nSELECT now(), now() AT TIME ZONE \'UTC\';',
     [('切换会话时区显示同一时刻','显示值可变但绝对时刻不变','字段类型和会话配置'),('无时区字符串写入时间字段','解释依赖具体类型和上下文','输入约定与目标列类型'),('中文显示异常','需要核对编码而非调整时区','原始字节和客户端编码')],
     '报表按日汇总时要明确业务时区，不能默认数据库会话时区就是业务规则。交换接口也要带清楚的时间表示。','业务含义|区分日期本地时间与绝对时刻>字段类型|选择匹配的时间语义>会话设置|影响解析与显示方式>接口交换|显式表达时区和编码'),
    ('03','postgres96-backup-restore','深入 PostgreSQL：pg_dump 成功后还要验证恢复','pg17','备份文件生成并不说明能恢复应用。角色、扩展和依赖同样影响还原结果。',
     '逻辑备份保存对象定义与数据，格式决定使用 psql 还是 pg_restore。单库备份不会自动包含集群全部全局对象。目标服务器版本、扩展与权限需要提前准备，不能等故障发生才发现缺少依赖。',
     '在测试库生成自定义格式备份，先查看目录，再还原到独立空库。检查表数、约束和少量业务不变量，不覆盖原库。','bash','pg_dump -Fc -d demo -f demo.dump\npg_restore --list demo.dump\n# 目标 demo_restore 需事先独立创建\npg_restore -d demo_restore demo.dump',
     [('备份文件非空','仍不证明对象和数据完整','还原日志与错误'),('目标缺少扩展或角色','部分对象可能无法建立','依赖清单和权限映射'),('表行数一致','还需检查约束与业务关联','关键查询与完整性规则')],
     '备份应保留在独立故障域并控制访问。恢复演练使用脱敏或受控数据，不能把备份文件直接放到公开下载目录。','逻辑导出|保存明确数据库的对象与数据>依赖准备|确认角色扩展与版本>独立还原|避免覆盖源数据库>业务校验|核对约束和关键关系'),
    ('04','postgres96-mvcc-vacuum','深入 PostgreSQL：更新为什么会留下旧版本','pg17','表频繁更新后体积增长，不一定是数据行数增加。MVCC 需要保留对其他事务仍可见的旧版本。',
     'MVCC（多版本并发控制）通过行版本支持并发可见性，旧版本在不再需要后才能清理。VACUUM 回收可复用空间并维护可见性相关信息，普通 vacuum 不等于把文件立即缩小。长事务会阻碍部分清理进度。',
     '用演示表进行多次更新，观察统计视图和活动事务。先找长事务来源，再考虑是否需要更重的维护操作。','sql','SELECT relname, n_live_tup, n_dead_tup\nFROM pg_stat_user_tables WHERE relname=\'demo_rows\';\nSELECT pid, xact_start, state FROM pg_stat_activity;',
     [('持续更新同一批行','可能产生大量死元组','存活与死元组统计'),('长事务一直不结束','旧版本可能继续被保留','最老事务开始时刻'),('运行普通 VACUUM','空间可复用但文件不必缩小','表文件大小与后续复用情况')],
     '统计视图包含估计值，不能作为逐行精确计数。维护方式还需考虑锁、I/O 与业务窗口，不应直接在繁忙实例尝试重写表。','并发事务|各自需要正确可见版本>行版本更新|旧版本暂时保留>清理条件|确认不再被活动事务需要>空间复用|区分回收与文件缩小'),
    ('04','postgres96-explain-analyze','深入 PostgreSQL：EXPLAIN ANALYZE 会真正执行语句','pg17','执行计划能解释访问路径，但带 ANALYZE 的检查不是纯静态查看。',
     'EXPLAIN 给出规划估计，ANALYZE 执行并收集实际行数和时间。循环次数需要与每次平均值一起看，节点时间也不宜简单相加。BUFFERS 有助观察缓存与读取，但不能单独证明磁盘物理 I/O 全部细节。',
     '先对只读演示查询执行，比较估计与实际行数。涉及写语句时必须意识到副作用，必要测试也应在可回滚事务和隔离环境。','sql','EXPLAIN (ANALYZE, BUFFERS)\nSELECT id FROM demo.orders\nWHERE owner_id=7 ORDER BY id LIMIT 20;',
     [('估计行数与实际相差较大','可能影响连接和扫描选择','每节点 rows 与 actual rows'),('内层节点 loops 很多','累计成本需结合循环次数','每次输出与调用次数'),('对 UPDATE 使用 ANALYZE','更新会实际执行','事务边界与最终数据状态')],
     '缓存和并发负载影响时间，不能只看一次最好结果。优先找数量级差异与不必要工作，再比较局部优化。','规划估计|查看预测行数与路径>真实执行|ANALYZE 收集运行结果>循环缓冲|结合 loops 与 BUFFERS>优化判断|寻找估计偏差和多余工作'),
    ('04','postgres96-index-types','深入 PostgreSQL：B-tree、GIN 与 BRIN 怎样选择','pg17','数据库支持多种索引，并不表示新类型就更适合当前查询。要从操作符和数据分布开始。',
     'B-tree 常用于等值、范围与排序，GIN 适合某些多值包含检索，BRIN 利用块范围摘要，适合数据与物理顺序有较强相关的场景。索引支持的操作符决定能服务哪些条件，体积小也不代表过滤精确。',
     '为独立时间序列表比较 B-tree 与 BRIN，再为 jsonb 条件单独研究 GIN。每次只评估一类查询与数据分布。','sql','CREATE INDEX ix_event_time ON demo.events USING brin(event_time);\nEXPLAIN SELECT id FROM demo.events\nWHERE event_time >= \'2017-01-01\'::timestamp;',
     [('时间与物理写入顺序相关','BRIN 可能有效跳过块范围','相关性与重新检查行数'),('数据顺序高度混乱','范围摘要过滤能力可能下降','同一区块时间分布'),('查询使用不匹配操作符','索引未必能参与定位','操作符类与执行计划')],
     '建索引有写入与维护成本。比较时包含构建、更新和存储开销，不能只比较一条查询的耗时。','查询操作符|确定等值范围包含或排序>数据分布|检查相关性与选择率>索引机制|匹配树倒排或块摘要>实际计划|核对过滤回表与维护成本'),
    ('05','postgres96-jsonb-relational-boundary','深入 PostgreSQL：JSONB 与关系字段各放什么','pg17','把所有字段塞进 JSONB 很灵活，也可能让约束、统计和查询变得难以管理。',
     '稳定身份、关联与关键约束适合显式列，变化较多的扩展属性可以放 JSONB。JSONB 不保留原始文本的全部格式与重复键，不能作为需要字节级原文留存的替代。GIN 能支持部分包含查询，但仍要匹配操作符。',
     '用设备扩展参数作演示，设备编号独立成列，型号属性放 JSONB。先验证缺字段、数字与字符串类型差异。','sql','SELECT id FROM demo.devices\nWHERE attrs @> \'{"kind":"sensor"}\'::jsonb;\nCREATE INDEX ix_device_attrs ON demo.devices USING gin(attrs);',
     [('关键关联字段藏在任意 JSON 中','会增加约束和连接难度','业务主键与关系定义'),('同字段有数字和字符串','查询语义可能不同','JSON 值的实际类型'),('要求保留原始文档字节','JSONB 不是原文存档','原始文本与结构化解析结果')],
     '灵活字段也需要版本和校验规则。长期任意写入会把模式治理推迟到每个查询里，不能因为数据库接受 JSON 就省略数据设计。','业务字段|分离稳定关系与扩展属性>类型约束|检查 JSON 值实际类型>检索条件|选择匹配的包含操作符>存档要求|原文字节与结构化数据分别保留'),
    ('05','postgres96-recursive-cte-tree','深入 PostgreSQL：递归 CTE 查询组织树','pg17','查询一个部门及其所有下级，固定写几层 join 无法覆盖不确定深度。递归查询可以表达层级扩展。',
     '递归 CTE（公共表表达式）先提供起始集合，再反复从上一轮结果扩展。树数据如果存在环，递归可能无法自然结束，因此需要路径记录或业务约束。输出顺序也要显式指定，不凭递归执行顺序猜测。',
     '使用匿名部门表，路径数组记录已经经过的编号。九点六没有后续版本的 SEARCH/CYCLE 语法，环检测在查询中显式表达。','sql','WITH RECURSIVE tree AS (\n SELECT id,parent_id,ARRAY[id] AS path FROM demo.dept WHERE id=1\n UNION ALL\n SELECT d.id,d.parent_id,t.path||d.id\n FROM demo.dept d JOIN tree t ON d.parent_id=t.id\n WHERE NOT d.id=ANY(t.path)\n) SELECT * FROM tree ORDER BY path;',
     [('部门层级超过预期','递归可继续扩展而非固定层数','每轮新增节点与路径'),('数据意外形成环','路径条件应防止重复进入','当前编号是否已在路径中'),('希望按树顺序展示','需要明确排序规则','最终 ORDER BY 而非执行偶然顺序')],
     '递归查询不能替代写入时的数据治理。修改父节点前也要防止建立环，深树和宽树还需评估返回规模。','起始节点|明确查询根与权限范围>递归扩展|从上一轮连接子节点>路径约束|避免再次访问已有节点>结果排序|以明确规则生成展示顺序'),
    ('05','postgres96-window-functions','深入 PostgreSQL：窗口函数保留明细又计算排名','pg17','既想显示每条订单，又想看到该客户最近一单，普通聚合会把明细折叠掉。窗口函数提供另一种表达。',
     '窗口函数在分区内计算，同时保留每行。row_number 与 rank 对并列的处理不同，窗口排序也不等于最终结果排序。累计计算还需理解 frame（窗口帧）默认范围，同值排序字段可能改变直觉。',
     '以客户分区，按创建时间和编号倒序编号，再在外层筛选第一行。唯一次级键让最近一单的选择可重复。','sql','SELECT * FROM (\n SELECT id,owner_id,\n row_number() OVER (PARTITION BY owner_id\n   ORDER BY created_at DESC,id DESC) AS rn\n FROM demo.orders\n) x WHERE rn=1;',
     [('两单创建时间相同','仍由编号确定唯一顺序','完整窗口 ORDER BY'),('改用 rank 处理并列','可能返回多个相同名次','排名函数的并列规则'),('窗口有排序但外层没有','最终展示顺序仍不保证','最终查询的 ORDER BY')],
     '窗口计算可能需要排序和额外内存，数据量大时查看执行计划。不要因为 SQL 更短就忽略中间结果规模。','明细输入|保留每个订单行>窗口分区|按客户分开计算>窗口顺序|定义排名与累计依据>外层筛选|按结果选择而不混淆最终排序'),
    ('06','frontend-state-draft-versus-saved','前端深入研究：编辑草稿与服务器事实分开保存','front17','用户正在修改表单时，后台刷新覆盖了输入，通常说明临时草稿与已保存记录共用了同一状态。',
     '服务器记录是已确认事实，编辑模型是尚未提交的意图。进入编辑时复制必要字段并保存版本，取消丢弃草稿，保存成功才更新事实。深层对象如果只做浅复制，仍可能共享可变子对象。',
     '用订单备注编辑演示两个模型，刷新时只更新事实并提示冲突，不自动覆盖用户输入。保存请求携带原版本。','javascript','var saved = { id: 1, remark: "old", version: 3 };\nvar draft = { remark: saved.remark };\n// cancel: discard draft\n// save: send draft + expected version\n// success: replace saved with verified response',
     [('后台事实刷新而用户仍编辑','草稿不能被静默覆盖','两个状态对象是否独立'),('用户点击取消','服务器事实保持不变','临时修改是否已污染原对象'),('保存时版本已变化','应提示冲突并重新核对','请求版本与服务端版本')],
     '草稿保存到浏览器还涉及隐私和期限。敏感字段不应无条件持久化，退出账号时也要处理本地残留。','服务器事实|只放已确认记录>编辑草稿|独立保存临时意图>版本提交|核对编辑依据是否仍有效>保存取消|分别更新事实或丢弃草稿'),
    ('06','frontend-css-grid-progressive','前端深入研究：新布局能力要配合回退方案','front17','新浏览器里布局漂亮，旧浏览器却堆成一列，说明技术选型需要覆盖真实使用环境。',
     '渐进增强先提供可读可用的基础结构，再在支持时增加布局能力。CSS Grid（网格布局）与 Flexbox 适用维度不同，检测支持可以帮助选择样式，但不代表所有边界都一致。内容顺序不应依赖视觉位置才能理解。',
     '演示用普通块布局作为基础，在支持 grid 时改成两列。测试窄屏、长标题和缺图，不只看设计稿尺寸。','css','.cards > article { margin-bottom: 16px; }\n@supports (display: grid) {\n  .cards { display: grid; grid-template-columns: 1fr 1fr; }\n}\n/* 保留不支持 grid 时的可读基础排布 */',
     [('浏览器不支持网格','基础内容仍应可读可操作','回退布局的任务完成情况'),('标题特别长','需要检查最小尺寸和换行','实际内容而非短占位文字'),('视觉重排改变顺序','键盘与阅读顺序仍按 DOM 分析','焦点顺序和内容语义')],
     '支持检测只判断语法能力，不能代替目标设备验证。对关键后台页面，稳定操作比追求最新布局效果更重要。','基础文档|保证自然阅读与操作顺序>能力检测|识别可用布局语法>增强样式|支持时启用二维网格>回退验证|旧环境仍能完成核心任务'),
    ('06','frontend-component-contract','前端深入研究：组件接口要表达状态与事件','front17','组件把界面拆小，却可能通过共享变量重新绑在一起。复用的关键是明确输入和输出。',
     '列表组件接收数据与加载状态，向上报告选择或翻页意图，不直接猜测全局业务。加载中、空结果与加载失败是不同状态。组件事件表达用户动作，是否真的保存成功由业务层按服务端结果决定。',
     '以分页列表为例列出输入和事件，再用固定数据独立渲染。不要让展示组件直接改父级查询对象。','text','inputs: rows, loading, error, page, total\nevents: page_requested, row_selected, retry_requested\nowner: parent coordinates request and verified result',
     [('加载失败但 rows 为空','应显示错误而非没有数据','loading error empty 三种分支'),('用户点击下一页','组件报告意图而不伪造数据','请求事件与服务端响应'),('两个页面复用同一组件','不应共享隐式查询状态','每个实例的输入与内部状态')],
     '抽象层级要匹配实际复用。只出现一次的复杂业务可先保持清晰局部结构，避免为“通用”暴露几十个互相矛盾的开关。','显式输入|数据与状态分别提供>展示组件|不擅自修改父级事实>用户事件|向上表达选择与请求>业务协调|按真实响应更新页面'),
    ('07','android23-environment-toolchain','Android 开发起步：JDK、SDK、Gradle 与 IDE 的关系','android17','安装 Android Studio 后，工程仍可能因为 SDK 或 Gradle 版本不匹配而无法构建。各工具承担不同任务。',
     'JDK 运行编译工具，Android SDK 提供平台 API 与打包工具，Gradle 执行构建，Android 插件连接平台任务。工程 wrapper 固定 Gradle 版本，不能只看系统安装的 gradle。模拟器系统版本与 compileSdk 也不同。',
     '先创建空工程，固定 wrapper 与插件，再核对 SDK Manager 中 API 25 平台。下载来源和许可按官方工具处理，不使用来路不明的整包替换。','text','IDE: Android Studio 2.3\nJDK: 8\nGradle wrapper: 3.3\nAndroid plugin: 2.3.0\ncompileSdkVersion: 25\nBuild Tools: 25.0.2',
     [('系统 Gradle 与 wrapper 不同','工程通常按 wrapper 声明执行','gradle-wrapper.properties'),('缺少编译平台','无法解析需要的平台资源','SDK Manager 已安装项目'),('模拟器版本较低','运行能力还受 minSdk 与 API 使用影响','编译和运行版本分别记录')],
     '历史工具链需要匹配当时依赖，不适合直接照搬到今天的新工程。这里的版本组合用于理解这一阶段的构建关系。','开发工具|IDE 组织工程与调试入口>构建执行|wrapper 固定 Gradle 版本>平台工具|SDK 提供 API 与打包能力>运行设备|按系统版本验证实际行为'),
    ('07','android23-gradle-project-structure','Android 工程结构：模块、Manifest 和资源目录','android17','找不到入口页面、资源引用失败或依赖没有生效，常常是修改了错误层级的文件。',
     '根工程管理公共仓库与插件，app 模块定义应用构建。Manifest（应用清单）声明组件与权限，res 目录按类型与限定符保存资源。R 类由构建生成，不应手工编辑生成结果。',
     '从空 Activity 工程检查文件位置，再改一个字符串资源验证。应用标识与 Java 包名有联系但不是可随意混用的同一字段。','text','root build.gradle -> repositories and plugin classpath\napp/build.gradle -> applicationId, SDK, dependencies\napp/src/main/AndroidManifest.xml -> components\napp/src/main/res/layout -> XML layout\napp/src/main/res/values -> strings and styles',
     [('把模块配置写到根层级','可能无法形成预期构建任务','插件应用位置与错误信息'),('手工修改生成的 R 类','下一次构建会覆盖且不能治本','真正的资源定义错误'),('不同环境需要不同值','可使用受控资源或构建配置','最终 APK 中实际打包内容')],
     '工程可配置不等于应把密钥放进构建文件。签名凭据和环境私密值通过受控本地配置或发布环境提供。','根工程|管理插件与公共依赖来源>应用模块|定义应用标识和构建参数>资源清单|声明组件权限和页面内容>生成产物|R 与 APK 由构建过程生成'),
    ('07','android23-first-activity-install','Android 从零到应用：让第一个 Activity 真正在设备运行','android17','编辑器能预览布局，不代表 APK 已安装，更不代表启动入口配置正确。',
     'Activity（界面组件）通过清单参与应用启动，onCreate 中加载布局资源。安装包、启动意图与运行日志分别提供不同证据。模拟器运行成功后，真机还可能有权限、分辨率和厂商行为差异。',
     '制作只有按钮和状态文字的页面，点击后更新文本。先用 adb 确认设备，再安装演示调试包，观察启动异常。','java','public class MainActivity extends Activity {\n  @Override public void onCreate(Bundle state) {\n    super.onCreate(state);\n    setContentView(R.layout.activity_main);\n  }\n}',
     [('设备没有出现在 adb 列表','IDE 无法凭空完成安装','连接授权与设备状态'),('布局预览正常但启动崩溃','需要查看运行期异常','logcat 中首个应用错误'),('应用安装成功','仍要点击并验证交互结果','真实启动页面与按钮状态')],
     '安装失败应保留完整原因，签名冲突、空间不足与最低系统版本不同，不能都靠反复重装解决。','设备连接|确认 adb 可识别授权设备>APK 安装|核对包名签名与系统要求>启动入口|清单决定可启动组件>交互结果|验证页面实际行为'),
    ('08','android-activity-lifecycle-state','Android 深入：旋转屏幕后为什么重新创建页面','android17','旋转后输入消失，不一定是控件保存失效，而是页面经历了重新创建。',
     '配置变化可能销毁并重建 Activity。成员字段只属于当前实例，不能作为长期状态依据。短小 UI 状态可通过实例状态保存，持久业务数据放入合适存储，恢复时再从权威来源核对。',
     '在生命周期回调打印匿名状态，输入文本后旋转并观察实例变化。不要简单禁止全部配置变化来掩盖状态设计。','java','@Override protected void onSaveInstanceState(Bundle out) {\n  out.putString("draft", draftText);\n  super.onSaveInstanceState(out);\n}\n// onCreate 中从 state 恢复短小的界面状态',
     [('旋转触发页面重建','新实例字段不会天然继承旧值','实例身份与生命周期日志'),('进程被系统回收后回来','不能只依赖静态变量恢复','持久数据与保存状态'),('业务已在服务端完成','恢复界面应重新核对真实状态','服务端记录而非旧按钮文本')],
     '实例状态不适合存放大图片和完整数据库。保存最小定位与编辑信息，再按生命周期恢复必要资源。','页面创建|建立本次 Activity 实例>用户编辑|形成临时界面状态>配置变化|旧实例可能被销毁>状态恢复|新实例按保存内容重建'),
    ('08','android-layout-density-units','Android 界面：dp、sp 与真实像素分开设计','android17','同一像素宽度在不同手机上显示大小不同。布局需要考虑密度和用户字体设置。',
     'dp（密度无关尺寸）用于常规布局，sp（可缩放文字尺寸）还受字体缩放影响。图片像素与显示尺寸不等价，固定高度遇到大字体可能裁切。不同资源限定符可以为设备条件提供适合版本。',
     '做一个标签加输入框的布局，测试窄屏和较大字体。触控区域与视觉图标大小分别检查，不只比较截图。','xml','<TextView\n android:layout_width="match_parent"\n android:layout_height="wrap_content"\n android:textSize="16sp"\n android:padding="12dp"\n android:text="演示说明"/>',
     [('设备密度变化','dp 对应像素数会不同','密度与最终像素尺寸'),('用户放大系统字体','文本高度可能增加','sp 缩放与容器裁切'),('使用固定像素布局','不同设备体验可能明显不同','实际屏幕密度与可用空间')],
     '布局自适应不意味着所有设备都一套固定尺寸。重要任务应在真实目标屏幕和字体设置下验证，资源体积也需要控制。','设计尺寸|区分布局单位与原始像素>设备密度|影响 dp 到像素映射>字体缩放|sp 随用户设置变化>实际布局|检查换行裁切和触控区域'),
    ('08','android-recyclerview-reuse','Android 列表：RecyclerView 复用时必须重绑完整状态','android17','快速滚动后某行出现别人的勾选或图片，通常是复用视图残留了旧状态。',
     'RecyclerView（可回收列表组件）复用 ViewHolder，绑定时不能只处理某些为真的分支。每次应按当前数据设置完整展示状态，点击事件要使用有效位置或稳定业务身份，不能永久捕获过期下标。',
     '使用 support-v7 25.3.1 的列表依赖，准备有图无图和不同选中状态的演示数据。快速滚动后逐行对照模型。','java','public void onBindViewHolder(RowHolder h, int position) {\n  Row row = rows.get(position);\n  h.title.setText(row.title);\n  h.checked.setChecked(row.selected);\n  h.image.setImageResource(row.hasImage ? R.drawable.demo : R.drawable.empty);\n}',
     [('旧行选中而新行未选中','绑定必须显式清除选中状态','每次 bind 设置的全部属性'),('异步图片晚于复用返回','不能写入已属于另一行的视图','请求标识与当前业务身份'),('列表删除使位置变化','旧下标不能作为永久业务编号','点击时的有效位置或稳定 id')],
     '复用提升滚动效率，也要求状态归属清楚。选中状态应保存于数据模型或明确状态容器，不只存在控件里。','数据模型|保存稳定业务身份与状态>视图复用|同一 holder 可展示不同记录>完整绑定|覆盖旧展示和异步归属>点击处理|按当前有效身份执行业务'),
    ('09','android-network-main-thread','Android 网络：请求放到后台，结果回到有效界面','android17','界面卡住或抛网络线程异常，说明请求执行位置需要与 UI 更新位置分开。',
     '主线程负责界面事件，耗时网络工作会影响响应。后台结果返回时，原 Activity 可能已销毁或切换到其他查询。连接和读取应有超时，错误状态不能伪装成空列表。',
     '用受控执行器进行 HttpURLConnection 请求，通过主线程处理器更新界面。代码为流程示意，还需关闭流、断开连接和处理生命周期。','text','worker: connect with connect/read timeouts\nworker: parse demo response and close resources\nmain thread: verify screen and request identity\nmain thread: render data or explicit error',
     [('请求期间旋转或离开页面','旧结果不应更新失效实例','页面与请求身份'),('服务器迟迟不响应','有界超时避免永久等待','连接和读取超时分别设置'),('网络错误却返回空数组','会误导用户认为没有数据','错误分支与真实空结果')],
     '后台线程也有数量上限。重复点击和重试要合并或限制，不能每次动作都创建无限新线程。','界面触发|生成本次请求身份>后台执行|有界等待并关闭资源>结果回传|切回主线程处理>界面有效性|只更新仍匹配的页面状态'),
    ('09','android-sqlite-upgrade','Android 本地存储：SQLite 建表与版本升级','android17','应用升级后本地表结构改变，直接删库重建会丢掉用户数据。升级需要有明确迁移路径。',
     'SQLiteOpenHelper 根据数据库版本调用创建或升级逻辑。新增列、回填数据与约束变化需要考虑旧版本输入。数据库版本只能前进到明确结构，不能只把版本号加一却不定义实际变化。',
     '从第一版演示表升级增加备注列，使用独立测试数据库检查旧数据保留。新安装与旧版升级都要走一遍。','java','public void onUpgrade(SQLiteDatabase db, int oldV, int newV) {\n  if (oldV < 2) {\n    db.execSQL("ALTER TABLE note ADD COLUMN remark TEXT");\n  }\n}',
     [('新装应用直接创建最新版','表结构应与迁移后目标一致','onCreate 与升级最终结构'),('旧用户跨多个版本升级','每一步必要变化都不能遗漏','旧版本到目标的完整路径'),('迁移中断或失败','应保留可恢复的数据状态','事务与失败处理')],
     '本地数据库不等于同步完成。若记录还要上传服务端，应单独保存待同步状态和幂等身份，避免升级时重复提交。','旧版结构|记录真实起始版本>迁移步骤|按版本条件执行必要变化>数据保留|校验旧记录和约束>目标结构|新装与升级结果保持一致'),
    ('09','android-runtime-permission','Android 权限：清单声明与运行时授权分别处理','android17','清单已经写了权限，功能仍然被拒绝，可能是运行系统与目标 SDK 采用了运行时授权机制。',
     'Android 6.0 起部分危险权限需要运行时请求，用户可以拒绝或后续撤销。请求应发生在真实功能需要时，并给出可理解用途。权限通过也不代表设备一定有对应硬件或资源当前可用。',
     '以相机演示先检查再请求，回调后继续相应动作。拒绝时保留替代路径，不在启动时一次索取所有未来可能使用的权限。','text','user selects camera feature\ncheck runtime permission\nif not granted: request with clear purpose\non result: continue or show usable alternative\nrecheck before later protected access',
     [('用户首次拒绝','应用核心界面仍应可使用','拒绝分支与替代操作'),('用户在设置中撤销','后续访问需要再次检查','当前权限状态而非旧缓存'),('已授权但相机被占用','仍可能出现资源访问错误','权限与设备资源状态分别判断')],
     '不要让权限说明承诺超过实际用途。只申请本轮确实需要的权限，测试时也要覆盖拒绝和撤销场景。','功能触发|先让用户理解真实用途>权限检查|区分清单与当前授权>结果处理|允许拒绝并提供替代>资源访问|授权后仍处理设备异常'),
    ('10','android-app-complete-notes','Android 小应用实作：从列表、编辑到本地保存闭环','android17','把控件分别跑通之后，需要一个完整用户任务来验证应用是否真正可用。这里用匿名笔记工具串起开发链路。',
     '列表显示已保存记录，编辑页维护草稿，保存动作提交本地数据库，返回列表后重新查询。空标题、取消编辑和重复点击都有明确规则。页面内存数据与数据库事实分开，可以避免返回后出现幽灵记录。',
     '先完成新增与修改，再加删除和搜索。每条记录使用稳定数据库编号，列表位置不能代替业务身份。','text','list -> open draft editor\nsave -> validate -> database transaction\nsuccess -> finish editor -> reload list\ncancel -> discard draft without changing saved record',
     [('编辑后点击取消','已保存记录不应被污染','草稿与持久记录是否独立'),('快速重复点击保存','不应生成多条同一编辑结果','按钮状态和保存身份'),('应用退出后重新打开','已确认记录仍能从数据库读回','重启后的真实数据')],
     '这个闭环只涵盖本地笔记，不等于云同步产品。同步、账号和附件会引入新的冲突与隐私问题，应作为后续明确范围。','已存列表|从数据库读取确认记录>编辑草稿|临时状态独立维护>保存事务|校验后一次写入>返回刷新|重新读取真实持久结果'),
    ('10','android-apk-signing-release','Android 发布：调试包与正式签名包的区别','android17','调试安装没问题，替换正式包却失败，可能是签名身份不一致。应用升级依赖稳定发布身份。',
     'APK 签名标识发布者，升级需要符合签名与包身份要求。debug keystore（调试密钥库）不应作为正式长期发布凭据。版本号区分展示版本与用于升级判断的内部版本，二者需要一起维护。',
     '在离线受控环境保管正式签名文件，通过构建配置生成 release 包。示例只列非敏感字段，不公开密钥路径与密码。','text','applicationId = stable application identity\nversionCode = monotonically increased release number\nversionName = user-visible version label\nsigning material = controlled backup, excluded from source',
     [('相同包名但签名不同','通常不能作为原应用正常升级','实际证书身份与安装错误'),('只改显示版本文字','内部升级编号仍需正确增加','versionCode 与 versionName'),('签名文件丢失','会影响后续同身份发布','备份与访问责任')],
     '发布包还要检查日志、测试入口和私密配置。能生成 release APK 只是构建结果，不代表已经通过商店或用户验收。','应用身份|包标识保持明确稳定>版本编号|区分内部与展示版本>发布签名|受控保管长期身份>安装升级|用正式包验证数据保留'),
    ('10','android-release-acceptance-matrix','Android 交付：用一张场景表验证完整软件','android17','一台手机上点通一次，不足以说明应用可以交付。需要覆盖安装、升级、异常和生命周期。',
     '测试范围按真实使用条件组织：最低系统、目标分辨率、权限拒绝、网络中断和旋转重建。每项记录输入、实际现象和版本，不把计划执行写成已通过。修复后验证原问题及直接受影响路径。',
     '为笔记演示应用准备新装、旧数据升级、空数据、长文本和快速重复操作场景。使用相同待发布 APK，避免测试的是另一份调试包。','text','artifact -> exact release APK identity\nscenarios -> install, upgrade, lifecycle, permissions, offline\nrecord -> input, device, actual result, issue\nacceptance -> confirmed task completion',
     [('调试包通过而发布包未测','结论不能自动沿用','产物签名与配置差异'),('系统回收后数据仍正确','说明相应恢复路径得到覆盖','真实恢复过程与数据来源'),('只记通过不留输入','后续难以复验','设备版本与具体操作条件')],
     '场景表应与应用风险匹配，不靠堆数量。最终交付还要包含安装说明、数据保存位置与可处理故障范围。','发布产物|固定实际验收的 APK>环境矩阵|覆盖目标系统与设备条件>业务场景|包含异常和生命周期>结果记录|事实通过与待处理问题分开'),
    ('11','canbus-arbitration-physical-layer','车联网学习：CAN 仲裁、帧与物理层先分清','can17','接上两根线看到报文，只是研究开始。总线类型、波特率与终端匹配决定接入是否合理。',
     '经典 CAN 通过标识符参与仲裁，标识符本身不直接等于某个设备地址。数据字段需要上层协议定义，同一标识符在不同车型网段也可能有不同含义。控制器和收发器属于不同层次，电气接入不能靠软件猜测。',
     '先阅读适配器和目标网段资料，离线研究帧结构。台架断电测量与布线需按硬件手册进行，不在未知带电接口上试接。','text','application signal -> payload definition\nCAN controller -> frame and arbitration\ntransceiver -> electrical bus interface\nphysical network -> wiring, bitrate, termination',
     [('相同标识符出现在不同车型','不能自动解释为同一信号','车型版本与网段资料'),('软件接口已启动','不代表电气与波特率正确','实际接收错误和硬件条件'),('只看到数据字节变化','还不能推断控制用途','动作对照与协议证据')],
     '标准只定义部分通信机制，不包含大众尚酷全部信号字典。未知内容应保持待验证，不能用其他车辆的例子补成事实。','业务信号|依赖车型专用定义>CAN 帧|标识符与负载各有含义>控制器收发器|软件协议与电气接口分层>总线条件|核对布线波特率和终端'),
    ('11','socketcan-listen-capture','车联网学习：先用 SocketCAN 建立可重复的只读记录','can17','分析车灯动作需要带时间和实验条件的日志，只有一张报文截图很难区分因果。',
     'SocketCAN 把 CAN 接口接入 Linux 网络栈，can-utils 提供抓取等工具。candump 读取接口，不负责替硬件设置只听模式。日志应记录接口配置、动作时刻与实验编号，避免不同条件混在一起。',
     '先在虚拟接口观察命令格式。真实日志仅在确认接入条件后采集，公开分享使用合成数据并删除可识别信息。','bash','candump -L vcan0\n# vcan0 是先准备好的虚拟 CAN 接口\n# 真实接口只听模式与电气配置需另外核对',
     [('抓取工具正常运行','只证明工具进入接收流程','接口状态与是否实际收到帧'),('人工动作未记录时刻','难以对齐报文变化','动作时间与日志时间基准'),('不同会话混合分析','可能误把环境差异当信号','实验编号和配置快照')],
     '日志可见不代表已经理解信号。先构建静止、左灯、右灯和关闭的对照，再分析候选变化，不向真实总线主动重放未知帧。','实验条件|记录接口配置与会话身份>只读采集|接收帧并保留时间>动作标注|对齐人工操作时刻>离线分析|使用合成或脱敏日志复验'),
    ('11','scirocco-can-signal-candidates','大众尚酷 CAN 研究：怎样筛选左右灯候选信号','can17','某个字节与转向灯同时变化，只能成为候选证据，不能直接认定它就是控制位。',
     '车灯操作可能带来开关输入、状态广播、仪表反馈与网关转发等多种变化。需要固定车辆条件，多次执行关闭、左侧、关闭、右侧的对照，检查周期、位变化与其他动作的混杂。计数器与校验字段也会变化。',
     '在离线日志中按标识符、长度和时间分组，计算候选位变化。把原始观测与信号解释分列，不填写未经确认的真实标识符。','text','condition -> OFF / LEFT / OFF / RIGHT\nobservation -> id, dlc, timestamp, changed_bits\ninterpretation -> candidate input/status/control\nconfidence -> repeated evidence and unresolved confounders',
     [('每次左侧动作候选位变化','仍需排除周期计数与其他事件','多次独立重复的时间对齐'),('无动作时该位也变化','可能并非灯光状态位','静止基线日志'),('候选帧来自另一网段','还要解释网关与信号方向','接入位置和网络拓扑')],
     '本篇不声称已经找到尚酷左右灯控制报文。最终需要对应车型资料、方向验证和隔离台架证据，不能把相关性当成控制权限。','动作对照|分别记录关闭左侧与右侧>候选变化|按帧身份和位位置筛选>混杂排除|检查计数校验与其他状态>信号解释|输入反馈与控制分别判断'),
    ('12','scirocco-can-gateway-topology','大众尚酷车灯研究：网关可能隔开诊断口与目标模块','can17','诊断接口能看到一些车辆数据，不代表可以直接访问灯光模块所在的全部网段。',
     '车辆网络可能由多个速率与用途不同的网段组成，网关只转发允许的信息。诊断服务、状态广播与直接控制也有不同协议关系。看到灯状态可能是经过网关的反馈，并不证明同一路径接受控制请求。',
     '先根据对应车辆资料画出接入点、网关和目标模块的关系，所有未知连线标为待核实。没有资料时只做观测，不通过未知引脚试错。','text','observation point -> confirmed accessible bus\ngateway -> documented forwarding / diagnostic behavior\ntarget module -> model-specific interface\nunknown path -> unresolved, no guessed control frame',
     [('诊断口只出现部分状态','可能受网关与网段范围限制','实际接入网段与资料'),('能读取灯光反馈','不等于可沿同路由主动控制','信号方向与服务类型'),('换车型版本后行为不同','需重新核对模块与协议','车辆版本和软件身份')],
     '拓扑图应反映已知与未知，不用完整漂亮的连线掩盖缺证据。主动控制讨论必须建立在已确认的模块与协议上。','接入位置|先确认实际可见网段>网关边界|只转发允许的消息或服务>目标模块|需要车型对应的接口定义>证据状态|未知路径保留待核实'),
    ('12','can-vcan-turn-signal-state','车灯控制台架：先在 vcan 上验证左右灯状态机','can17','真实车辆协议尚未确认时，可以先验证上层状态机与通信封装，避免把软件逻辑错误带到硬件试验。',
     '用 OFF、LEFT、RIGHT 和 HAZARD 表达演示状态，状态到字节的映射完全由虚拟协议定义。虚拟帧只能证明软件发送、解析与状态迁移，不能证明大众尚酷真实灯光会接受相同内容。',
     '准备 vcan0 后，在一端接收合成帧，另一端只向该虚拟接口发送。下列标识符与字节是教学自定义值，严禁解释为车型实测。','bash','candump vcan0\n# 另一个终端：仅向虚拟接口发送合成协议\ncansend vcan0 123#0100\ncansend vcan0 123#0200\ncansend vcan0 123#0000',
     [('虚拟接口收到合成帧','说明软件链路可收发该格式','虚拟接口名和原始帧内容'),('左右状态快速切换','状态机应按定义保留唯一当前状态','事件顺序与解析结果'),('把合成值套到真实车辆','没有任何车型控制有效性依据','协议来源与台架验证范围')],
     '此实验不包含实车控制结果。协议适配应是可替换模块，真实映射必须单独验证后接入，不能靠修改接口名完成迁移。','上层意图|关闭左侧右侧分别表达>虚拟编码|自定义合成标识符与字节>vcan 通道|仅验证软件收发流程>状态回读|确认解析和切换逻辑'),
    ('12','can-control-feedback-stop','车灯控制研究：命令已发出与灯真正改变要分开验证','can17','发送函数返回成功，只说明数据进入某层发送流程，不能直接作为物理动作完成证据。',
     '台架控制要定义命令、接收确认、模块状态和独立物理观察。四者可能分别成功或失败。停止策略也需要独立设计，通信中断后不能无条件保持上次测试意图；具体默认状态由硬件与已确认协议决定。',
     '以独立指示灯台架记录请求编号、发送时刻、反馈与观察结果。先验证人工停止和断链处理，再开展重复动作，不使用未经确认的尚酷控制报文。','text','request -> encoded command -> transport acceptance\nmodule feedback -> reported state\nindependent observation -> actual lamp state\nstop path -> explicit timeout and operator stop condition',
     [('发送成功但没有状态反馈','任务不能标为物理完成','发送返回与反馈证据'),('模块报告状态但灯未变化','需要继续查执行与观测链路','独立光电或人工观察'),('通信中途断开','按台架规则进入可停止状态','超时策略和人工停止是否有效')],
     '进入实车阶段前仍需对应资料、适配器条件与静止验证方案。本文建立验收方法，不声称完成了真实车辆控制或道路测试。','控制意图|关联一次明确测试请求>传输结果|只证明某层接受发送>模块反馈|核对已确认的状态定义>物理观察|独立确认灯与停止策略')]
